package kz.printlab.service; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import kz.printlab.dto.ProfileUpdateRequest; import kz.printlab.entity.UserProfile; import kz.printlab.repository.*;
@Service public class UserProfileService {private final UserRepository users; private final UserProfileRepository profiles; public UserProfileService(UserRepository u,UserProfileRepository p){users=u;profiles=p;} private UserProfile current(){String email=SecurityContextHolder.getContext().getAuthentication().getName(); var u=users.findByEmail(email).orElseThrow(); return profiles.findByUserId(u.getId()).orElseThrow();}
@Transactional(readOnly=true) public ProfileUpdateRequest getCurrentProfile(){var p=current();var r=new ProfileUpdateRequest();r.setFullName(p.getFullName());r.setCity(p.getCity());r.setPhone(p.getPhone());r.setDeliveryAddress(p.getDeliveryAddress());return r;} @Transactional public void updateCurrentProfile(ProfileUpdateRequest r){var p=current();p.setFullName(r.getFullName());p.setCity(r.getCity());p.setPhone(r.getPhone());p.setDeliveryAddress(r.getDeliveryAddress());}}
